LETTERS = "ABCD"

def _item(qid, type_id, category, stem, options, key_index, explanation, reasons, extra=None):
    item = {
        "id": qid, "typeId": type_id, "category": category, "stem": stem,
        "options": [{"id": LETTERS[i], "text": text} for i, text in enumerate(options)],
        "correctAnswer": LETTERS[key_index], "explanation": explanation,
        "distractorExplanations": {LETTERS[i]: reasons[i] for i in range(4) if i != key_index},
    }
    if extra:
        item.update(extra)
    return item


